// Starter decks: 6 characters + 2 spells. Bio and Fire swap a 7th character for a spell.
THEMES.find(t=>t.id==='bio').cards=['mutant','zombie','rats','virologist','hazmat','mosquitoes','outbreak','genesplice'];
THEMES.find(t=>t.id==='fire').cards=['firechief','firetruck','firefighter','smokejumper','dalmatian','waterbomber','backdraft','waterbomb'];
CARDS.plague.unlock=60; CARDS.hydrant.unlock=60;

// Every card each arena offers in its deck builder (starters first, then Trophy Road unlocks).
const POOL_EXTRA={
  law:['stenographer','paralegals','prosecutor','usher','witnessstand','defense','notary','chancellor','justices','clerk','injunction','summons'],
  finance:['taxman','broker','interns','loanshark','vc','accountant','vault','ceo','piggy','whale','auditor','ratehike','ipo'],
  space:['cadets','engineer','astronomer','chimp','spacewalker','blackhole','miner','flightdir','satellite','spacedog','solarflare','gravitywell'],
  fbi:['interrogator','k9','forensics','agents','bombsquad','gadget','seccam','director','doubleagent','negotiator','emp','teargas'],
  bio:['plague','labtechs','geneticist','cloner','slime','toxicologist','labmonkey','decon','subjectzero','shroom','cropduster','antidote','horde'],
  hospital:['dentist','pharmacist','medinterns','radiologist','psychiatrist','gurney','hypochondriac','chiefmed','skeletons','morphine','quarantine'],
  kitchen:['butcher','critic','linecooks','sommelier','barista','meatball','hotsauce','nonna','dishwasher','rollingpin','orderup'],
  fire:['hydrant','investigator','firecadets','climber','smokediver','marshal','hosecrew','proximity','hotshot','firealarm','emtff','foamcannon','sprinkler','firetornado'],
  build:['jackhammer','scaffolders','surveyor','mixer','electrician','plumber','towercrane','foreman','steamroller','bricklayer','collapse','concrete'],
  rock:['stagediver','roadies','bassist','pyro','boyband','synth','speakers','diva','headbanger','hypeman','spotlight','feedback'],
  dog:['huskies','poodle','corgis','bulldog','greyhound','beagle','stbernard','retriever','shiba','pom','bathtime','bellyrubs'],
  sports:['cheerleaders','energydrink','baller','goalie','sumo','golfer','hockey','slamdunk','swimmer','coach','mascot','skater'],
  art:['sculptor','splatter','ballerina','pottery','glassblower','livingstatue','caricaturist','museum','icesculptor','popartist','gargoyle','artthief'],
  film:['makeup','slowmo','villain','dramaqueen','superhero','pirate','voice','sequel','childstar','moviestar','monster','trailer'],
  influencer:['gamer','likebomb','beauty','dancer','asmr','memelord','troll','comments','paparazzi','podcast','travel','mukbang'],
  zoo:['kangaroo','cagedrop','flamingo','skunk','lion','giraffe','cheetah','snakepit','hippo','trainer','panda','bats'],
};
for(const th of THEMES){ th.pool=th.cards.concat(POOL_EXTRA[th.id]||[]).sort((a,b)=>(CARDS[a].unlock||0)-(CARDS[b].unlock||0)); for(const id of th.pool) CARDS[id].theme=CARDS[id].theme||th.id; }
for(const k in CARDS){ CARDS[k].id=k; if(CARDS[k].unlock==null) CARDS[k].unlock=0; }
